-- Generated by tools/prepare_story.py from docs/story.md; edit the reviewed script.
return {
    {key="before-01", phase="before", level=1, lines={
        {"mara", "Hold on to something! The Marigold doesn't like this beach, and the feeling's mutual!", story.SHOUT},
        {"elena", "The Lost Valley. Thirty years of rumours, and a gate in the cliff, standing open.", story.THOUGHT},
        {"elena", "Look at the arch. Every stone is cut to ring. The whole gate is an instrument."},
        {"mara", "It's ticking, is what it is. Elena, your foot's on a loose one."},
        {"elena", "Oh. Oh, that's a trigger. Mara, run!"},
        {"mara", "Under! Get under it! Now!", story.SHOUT},
        {"adrian", "Well. That was the door. I assume there's another way out."},
        {"elena", "You hired me to record this place, Adrian. Nothing leaves the valley. That was our deal."},
        {"adrian", "Of course. I've a letter here, to be opened when we find the Heart of the Sun. Pure sentiment."},
        {"mara", "Who carries a sealed letter into a booby trap?"},
        {"adrian", "A man with excellent manners."},
    }},
    {key="after-01", phase="after", level=1, lines={
        {"tomas", "You rang the gate. It hasn't rung in a very long time. I heard it from the archive."},
        {"elena", "I'm Dr Voss, and this island isn't on any chart. Who are you?"},
        {"tomas", "Tomas Reed. I keep the archive. Pitch your camp away from the cliff. It crumbles after rain."},
        {"mara", "A librarian behind a booby-trapped door. I've had stranger Tuesdays, but not many."},
        {"tomas", "Some doors close for a reason, Miss Bell."},
    }},
    {key="after-02", phase="after", level=2, lines={
        {"elena", "These sunstones didn't break with age. They split from the inside, every edge clean."},
        {"mara", "Snake. Big one. On your boot. Don't panic, I'm calling him Gerald."},
        {"adrian", "I'll keep this broken one. A souvenir. Nobody will miss half a stone."},
        {"elena", "Put it in your pocket, then, and remember the deal. Nothing leaves the valley."},
        {"tomas", "Stone does many things, given time. So does Gerald. I'd step back."},
    }},
    {key="after-03", phase="after", level=3, lines={
        {"elena", "Strike this stone and it hums. They're tuned to the same note as the gate."},
        {"tomas", "They sang once. Every noon, the whole valley, from the temple down."},
        {"elena", "You make it sound as if you'd heard it."},
        {"tomas", "It's in the records."},
        {"elena", "A temple that sings doesn't simply stop. Someone silenced it.", story.THOUGHT},
    }},
    {key="after-04", phase="after", level=4, lines={
        {"mara", "Good water. And a lovely brass pump, from entirely the wrong century."},
        {"elena", "Threaded fittings. Someone was here before us, and not so long ago."},
        {"adrian", "Impossible. No expedition has ever been recorded here. I checked very carefully."},
        {"mara", "Funny thing to check so carefully."},
        {"tomas", "The spring runs lower every year. I'd drink while you can."},
    }},
    {key="after-05", phase="after", level=5, lines={
        {"mara", "Elena, the Marigold's radio. Someone's on our frequency. Someone polite."},
        {"kessler", "Good afternoon, Dr Voss. Kessler, of the Meridian Society. Do give Mr Vale my regards."},
        {"kessler", "He owes us rather a lot. When you find the Heart of the Sun, we shall be along to collect."},
        {"elena", "Adrian. Who is that?"},
        {"adrian", "My creditors. They're very good at finding people. It's most of what they do."},
        {"mara", "And a ship. The Halcyon. He says she sails in a fortnight."},
    }},
    {key="after-06", phase="after", level=6, lines={
        {"elena", "Mara, touch this wall. Is that... frost?"},
        {"mara", "In this heat? I'm sweating through my good jacket."},
        {"tomas", "The lower halls are cold now. It climbs a little higher every year."},
        {"elena", "Climbs from where?"},
        {"tomas", "Mind your footing down there, Dr Voss. The floors are older than the frost."},
    }},
    {key="after-07", phase="after", level=7, lines={
        {"elena", "Raiders. It has to be. They smashed the stones and drove everyone out."},
        {"adrian", "A tidy theory. Raiders, however, rarely sweep up."},
        {"elena", "...Every tool on its hook. Every door latched. And frost split those stones, not raiders."},
        {"mara", "Nobody robbed these people. They packed. And every road in the valley runs down to the beach."},
        {"elena", "I was wrong, then. So who silenced the temple, and why would a whole valley leave on purpose?"},
    }},
    {key="after-08", phase="after", level=8, lines={
        {"elena", "If we find the Heart, Kessler sails in and takes it. Perhaps we should stop digging."},
        {"mara", "And if we stop, the frost takes the valley instead. Pick your thief."},
        {"tomas", "The frost passed the first terrace last night. I'd not planned on it so soon."},
        {"elena", "Planned on it? Tomas, what do you know?"},
        {"tomas", "That you should dig faster."},
    }},
    {key="after-09", phase="after", level=9, lines={
        {"mara", "Best stall in the market, and look what's under the floor. Six-sided stonework."},
        {"elena", "Six sides, six locks. It's a seal, and it runs right under the temple terrace."},
        {"adrian", "Then the Heart of the Sun is beneath it. How marvellous."},
        {"elena", "You sound very sure."},
        {"adrian", "I'm an optimist. It's very nearly a profession."},
    }},
    {key="before-10", phase="before", level=10, lines={
        {"elena", "Last lock. Whatever stopped the song is under here."},
        {"mara", "Or a very fancy floor. With spikes. These people do love a spike."},
        {"tomas", "Go carefully. Some things are quiet for a reason."},
    }},
    {key="after-10", phase="after", level=10, lines={
        {"mara", "The floor's moving! Everybody off the middle!", story.SHOUT},
        {"elena", "It isn't falling, it's opening. Stairs, going down. And at the bottom..."},
        {"elena", "A sun of solid gold, wide as a cartwheel. And cold as a well."},
        {"adrian", "The Heart of the Sun. Elena, we've actually..."},
        {"elena", "Look closer. That's a socket. The Heart was here, and someone cut it out."},
        {"mara", "Who steals the heart out of a temple?"},
        {"elena", "Someone with good tools. They left one behind. A steel chisel, thirty years old at most."},
        {"mara", "Any maker's mark?"},
        {"elena", "Vale and Sons."},
        {"tomas", "So. He sent his boy.", story.THOUGHT},
        {"elena", "Adrian. Why is your name on this?"},
        {"adrian", "You'd better sit down, Elena. That chisel was my father's."},
    }},
    {key="before-11", phase="before", level=11, lines={
        {"adrian", "Cornelius Vale, my father. He came here thirty years ago with eleven men and a great many crates."},
        {"adrian", "None of them came home. I was five. All that ever reached me was this envelope, through a lawyer."},
        {"elena", "So you lied to get me here."},
        {"adrian", "You'd never have come for a missing man. You came for a lost valley."},
        {"mara", "And Kessler? Where does he fit?"},
        {"adrian", "I borrowed against the Heart to pay for all this. If we find it, it's theirs. If we don't, so am I."},
        {"mara", "Open the letter, then."},
        {"adrian", "\"When the Heart is found.\" It isn't found, is it? It's the one thing he ever asked of me."},
        {"elena", "Then we look for your father too. And you stop deciding what I get to know."},
        {"adrian", "That sounds entirely fair. I shall try to be bad at it."},
    }},
    {key="after-11", phase="after", level=11, lines={
        {"mara", "An ore cart on the old rail, and it still rolls. Who wants a lift down the terrace?"},
        {"elena", "Mara, that rail runs straight along the cliff edge."},
        {"mara", "It's fine! There's a brake! There was a brake! HOLD ON!", story.SHOUT},
        {"adrian", "I'd like it noted that I was against this from the start."},
        {"elena", "End of the line. His dig site. Your father hauled something heavy up here, Adrian."},
        {"adrian", "He built everything as though he'd be back on Monday."},
    }},
    {key="after-12", phase="after", level=12, lines={
        {"elena", "Supply crates. Food for twelve men for a year, and most of it never opened."},
        {"mara", "Nobody walks away from a year's tinned peaches."},
        {"adrian", "Careful with that lid, there's a wire. Ah. A spring trap. Father always did hate thieves."},
        {"elena", "He trapped his own larder? Who on an empty island was he afraid of?"},
    }},
    {key="after-13", phase="after", level=13, lines={
        {"elena", "Names cut into the courtyard wall. A fine old expedition habit."},
        {"adrian", "Cornelius Vale, first. Naturally. Then ten more I can read."},
        {"mara", "That's eleven. Twelve went in, counting him."},
        {"elena", "The twelfth has been cut away. Carefully, by someone who took his time."},
        {"mara", "Who chisels a man off a wall and then tidies up the dust?"},
    }},
    {key="after-14", phase="after", level=14, lines={
        {"mara", "Caught our friend on the radio at two in the morning. Guess who."},
        {"kessler", "You're very quiet tonight, Mr Vale. I do hope you haven't found something without me."},
        {"adrian", "Not a thing. A gold disc with a hole in it. You'd be bored stiff."},
        {"elena", "You told him about the disc?"},
        {"adrian", "I told him it was empty. A lie that sounds like bad news buys time. It's a family skill."},
    }},
    {key="after-15", phase="after", level=15, lines={
        {"elena", "The frost is over the second terrace. Tomas said a little every year."},
        {"mara", "That's not a little. That's ten feet since Sunday, and it's speeding up."},
        {"elena", "And it's spreading out from the temple, as if whatever warmed this valley was taken out of it."},
        {"elena", "But look at my map. One patch the frost won't touch, right in the middle of the valley."},
        {"mara", "So whoever cut the Heart out never took it off the island. It's hidden here, still warm."},
        {"elena", "Which means Kessler doesn't need to chase anyone. He only needs to land."},
    }},
    {key="after-16", phase="after", level=16, lines={
        {"mara", "Twelve bunks. Plates still on the table. They got up in the middle of supper."},
        {"elena", "Eleven bunks under thirty years of dust. And one with a clean blanket."},
        {"adrian", "One of them stayed. Someone alive can tell me what happened."},
        {"mara", "Alive for thirty years on what, tinned peaches?"},
        {"elena", "Whoever it is made that bed this morning."},
    }},
    {key="after-17", phase="after", level=17, lines={
        {"elena", "Their log. The last pages are torn out, all but one corner."},
        {"mara", "Three words on it. \"...until I return.\""},
        {"adrian", "My father's hand. Return from where? He was on an island."},
        {"elena", "Then he left it. And somebody stayed behind to tear out the rest."},
    }},
    {key="after-18", phase="after", level=18, lines={
        {"tomas", "Stop digging, Dr Voss. Take your plane and your financier and go home. Please."},
        {"elena", "The well has weeks left. You know that better than anyone."},
        {"tomas", "I know exactly what's left. I've measured it every morning for thirty years."},
    }},
    {key="after-19", phase="after", level=19, lines={
        {"elena", "He's kept every page in here dry. All but the ones we need."},
        {"mara", "Found a photograph in the back of a ledger. Twelve men on a beach."},
        {"adrian", "That's my father. And beside him, the thin lad in spectacles..."},
        {"elena", "Add a grey beard. That's Tomas."},
        {"mara", "Our twelfth name. Our librarian."},
        {"elena", "He told me the song was in the records. It isn't. He heard it."},
        {"mara", "And the radio says the Halcyon's sailed. Kessler sends his regards."},
    }},
    {key="before-20", phase="before", level=20, lines={
        {"elena", "He's gone down to the seal. He left a lamp burning so we'd follow."},
        {"adrian", "Let me speak to him first."},
        {"mara", "Not a chance. You'd offer him a loan."},
    }},
    {key="after-20", phase="after", level=20, lines={
        {"elena", "You took the Heart. You silenced the temple."},
        {"tomas", "I did. With Cornelius's own chisel, the morning he left. I would do it again."},
        {"elena", "Your silence is killing the spring. The frost that split those stones is your doing."},
        {"tomas", "I know what it costs. I have watched it climb for thirty years."},
        {"adrian", "Where is my father? Did you kill him?"},
        {"tomas", "Kill him? He made me swear. \"Keep it silent, Tomas, until I come back.\""},
        {"adrian", "Come back from where?"},
        {"tomas", "Ask where an entire people went, Mr Vale. Ask what they heard."},
        {"tomas", "I'm sorry. Some doors close for a reason."},
        {"mara", "The stairs! He's sealing the floor above us! Elena, the lamp's going out!", story.SHOUT},
        {"elena", "Then we find another way out. They always build another way out."},
    }},
    {key="before-21", phase="before", level=21, lines={
        {"mara", "Elena! Something's moving down here with us. It's Gerald. And he's going somewhere."},
        {"elena", "Snakes don't live in sealed rooms. Follow him. Where he goes, the air goes."},
        {"mara", "Out through the drains, behind a snake, all night. I will never be clean again."},
        {"elena", "I came to record a valley, and I've brought its creditors to it while it freezes. Some scholar."},
        {"adrian", "For the record, I brought the creditors. You only brought the arithmetic."},
        {"mara", "And Tomas left this on my pilot's seat. His journal. No note, just one page marked."},
        {"elena", "A star chart with six points ringed. It would only read properly from an observatory."},
        {"adrian", "He shut us in and then left us a map. He wants to be found."},
        {"elena", "Or he wants the Heart found before the well runs dry, and can't bring himself to say so."},
        {"mara", "The Halcyon's six days out. Frost, a ship and a runaway librarian. Best job I've ever had."},
    }},
    {key="after-21", phase="after", level=21, lines={
        {"elena", "His boot prints climb through the frost, then stop dead at running water."},
        {"mara", "And these aren't his. Hobnails, six men, fresh. They came in from the north cove."},
        {"adrian", "Kessler's put a landing party ashore ahead of his ship. Of course he has. I would have."},
        {"elena", "Then we're not the only ones following Tomas."},
    }},
    {key="after-22", phase="after", level=22, lines={
        {"adrian", "I've never held a pick in my life. I believe I've broken it."},
        {"elena", "That's a shovel, Adrian."},
        {"adrian", "Then I've broken that too. Send the bill to the Meridian Society."},
        {"mara", "Down! Lanterns on the ridge! That's snake number nine, and Kessler's men right behind it!", story.SHOUT},
    }},
    {key="after-23", phase="after", level=23, lines={
        {"elena", "The chart fits the dome. Six points, and none of them where a star should be."},
        {"mara", "Give it here. Those aren't stars, they're bearings. It's how I'd mark headings at sea."},
        {"elena", "Six places, then. And one of them is us."},
        {"adrian", "Why would anyone mark out five other islands?"},
        {"elena", "There's a note beside ours. \"Noon shadow, the old spring.\""},
    }},
    {key="after-24", phase="after", level=24, lines={
        {"elena", "At noon the temple's shadow falls right across the old fountain."},
        {"mara", "The warm patch on your map. The librarian's under a fountain, in a valley running out of water."},
        {"elena", "The one place the frost hasn't touched. We have to get that fountain running before Kessler does."},
    }},
    {key="after-25", phase="after", level=25, lines={
        {"mara", "Smoke on the horizon. The Halcyon. Two days, less if the wind holds."},
        {"kessler", "Mr Vale. Bring me the Heart, and every debt you have is paid. Noon tomorrow, on the beach."},
        {"elena", "Will you answer him?"},
        {"adrian", "Every debt, Elena. My house, my name, all of it, gone by noon tomorrow."},
        {"elena", "And the valley?"},
        {"adrian", "The valley was never mine."},
    }},
    {key="after-26", phase="after", level=26, lines={
        {"elena", "The basin's draining into a stair. And the air coming up is warm."},
        {"tomas", "You took your time. The only warm room left in the valley, and I've kept it for you."},
        {"mara", "Elena, look at his coat. It's glowing right through the cloth."},
        {"tomas", "The sea answered the Heart's song. A light on the water. The valley followed it centuries ago."},
        {"tomas", "Cornelius saw it too. \"Silence it until I'm back, or the whole world will come.\""},
        {"elena", "And he left you here to watch it freeze."},
    }},
    {key="after-27", phase="after", level=27, lines={
        {"elena", "Thirty years you've told yourself that silence keeps everyone safe."},
        {"tomas", "Did it? Look at the terraces. I kept my word and killed the place he loved."},
        {"elena", "So silence isn't safety. It's only a slower way to lose everything."},
        {"mara", "So we light it, and whoever's out there learns where we live. Lovely."},
        {"elena", "At noon, then. Before Kessler lands."},
    }},
    {key="after-28", phase="after", level=28, lines={
        {"mara", "Elena! The Heart's gone, and there's a dinghy missing from the beach!", story.SHOUT},
        {"elena", "Adrian, stop! That's the only warmth this valley has left!"},
        {"adrian", "It buys back every debt I have, Elena. There's nothing else I own that could."},
        {"kessler", "Splendid, Mr Vale. Pass it across, gently. And do wave goodbye to the doctor."},
        {"elena", "He's really done it. He's sold it.", story.THOUGHT},
    }},
    {key="after-29", phase="after", level=29, lines={
        {"adrian", "Elena, wait. Before you say a word, hold out your hands."},
        {"elena", "It's warm. This is the Heart. Then what did you give Kessler?"},
        {"adrian", "My souvenir. Half a sunstone, wrapped in my good jacket. Same weight. He didn't look."},
        {"adrian", "I opened the letter last night. \"My boy. Put it back. Then come and find me. C.V.\""},
        {"tomas", "He sealed that letter the morning he sailed. I never read it. I only posted it."},
        {"mara", "You conned the Meridian Society. With a jacket."},
        {"adrian", "It was a very good jacket."},
        {"elena", "And you took something out of the valley after all. The temple's whole again. Let's finish it."},
    }},
    {key="before-30", phase="before", level=30, lines={
        {"mara", "The Halcyon's anchored in the bay. I think Kessler's unwrapped the jacket."},
        {"kessler", "That was clever, Dr Voss. I'm coming ashore with forty men. You have until noon."},
        {"elena", "Then we finish by noon."},
        {"tomas", "Noon is when it sings."},
    }},
    {key="after-30", phase="after", level=30, lines={
        {"elena", "Set it in. Gently... there."},
        {"tomas", "Listen."},
        {"mara", "Is that all of it? The whole valley? Even the gate's ringing, and it's opening this time."},
        {"elena", "The frost's running off the terraces. The well is filling. Tomas, it's singing."},
        {"tomas", "Thirty years. I'm sorry, Cornelius."},
        {"mara", "Kessler's boats are turning back! The cliffs are humming, and his men won't land!", story.SHOUT},
        {"adrian", "Elena. You'd better look at the sea."},
        {"mara", "There! A light on the water! And past it, another one!", story.SHOUT},
        {"elena", "Five of them. Five bearings, just as he marked. Something out there is answering."},
        {"tomas", "That's where they went. All of them."},
        {"adrian", "And my father."},
        {"mara", "Worse news. The Halcyon's weighing anchor. She's not leaving. She's heading for the lights."},
        {"elena", "Then fill the Marigold's tanks, Mara. We have a race to win."},
    }},
}
